def double_elements(L):
    for i in range(len(L)):
        L[i] = L[i] * 2

L = [1, 4, 2]
double_elements(L)
print(L)  # Affiche [2, 8, 4]

def compter_positifs(L):
    compteur = 0
    for x in L:
        if x > 0:
            compteur += 1
    return compteur

print(compter_positifs([-2, 5, 0, 8, -1]))  # Affiche 2

def somme_carres(L):
    s = 0
    for x in L:
        s += x * x
    return s

print(somme_carres([2, 3, 4]))  # 29

def filtrer_superieurs(L, seuil):
    R = []
    for x in L:
        if x > seuil:
            R.append(x)
    return R

print(filtrer_superieurs([5, 12, 3, 18, 7], 10))  # [12, 18]

def separer_pairs_impairs(L):
    pairs = []
    impairs = []
    for x in L:
        if x % 2 == 0:
            pairs.append(x)
        else:
            impairs.append(x)
    return (pairs, impairs)

print(separer_pairs_impairs([1, 4, 7, 2, 9, 6]))  # ([4, 2, 6], [1, 7, 9])

def histogramme(L):
    d = {}
    for x in L:
        d[x] = d.get(x, 0) + 1
    return d

print(histogramme([2, 5, 2, 8, 5, 2]))  # {2: 3, 5: 2, 8: 1}

