def valider_ages(liste_ages):
    erreurs = []
    for i, age in enumerate(liste_ages):
        if not isinstance(age, int):
            erreurs.append(f"Indice {i} : type inattendu {type(age).__name__}")
        elif age < 0 or age > 120:
            erreurs.append(f"Indice {i} : âge hors plage [0, 120] -> {age}")
    if erreurs:
        raise ValueError("Données invalides :
" + "
".join(erreurs))
    return liste_ages

try:
    valider_ages([25, 30, -5, 40])
except ValueError as e:
    print(e)
# Affiche l'erreur pour l'indice 2 (âge -5)

