def premier_pair(L):
    for x in L:
        if x % 2 == 0:
            return x
    return None  # ou le bloc else: return None

print(premier_pair([1, 3, 5, 8, 9]))  # 8
print(premier_pair([1, 3, 5]))        # None

def tous_dans_intervalle(L, a, b):
    for x in L:
        if x < a or x > b:
            return False
    return True

print(tous_dans_intervalle([3, 5, 7], 0, 10))   # True
print(tous_dans_intervalle([3, 15, 7], 0, 10))  # False
print(tous_dans_intervalle([], 0, 10))          # True

def indice_derniere_occurrence(L, valeur):
    for i in range(len(L)-1, -1, -1):
        if L[i] == valeur:
            return i
    return -1

print(indice_derniere_occurrence([2, 5, 2, 8, 2], 2))  # 4
print(indice_derniere_occurrence([2, 5, 2, 8, 2], 7))  # -1

def valider_notes(notes):
    erreurs = []
    for i, note in enumerate(notes):
        if not isinstance(note, int):
            erreurs.append(f"Indice {i} : {note!r} n'est pas un entier")
        elif note < 0 or note > 20:
            erreurs.append(f"Indice {i} : {note} hors intervalle [0, 20]")
    if erreurs:
        raise ValueError("Notes invalides :
" + "
".join(erreurs))
    return notes

try:
    valider_notes([12, 15, 25, 8])
except ValueError as e:
    print(e)
